package com.company.tpm.assignment;import com.company.tpm.common.BaseEntity;import com.company.tpm.employee.Employee;import com.company.tpm.training.TrainingCourse;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="training_assignments",uniqueConstraints=@UniqueConstraint(columnNames={"employee_id","course_id","due_date"}))public class TrainingAssignment extends BaseEntity{@ManyToOne(optional=false,fetch=FetchType.LAZY)private Employee employee;@ManyToOne(optional=false,fetch=FetchType.LAZY)private TrainingCourse course;@Column(nullable=false)private LocalDate assignedDate;private LocalDate dueDate;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status=Status.ASSIGNED;public enum Status{NOT_STARTED,ASSIGNED,SCHEDULED,IN_PROGRESS,COMPLETED,FAILED,OVERDUE,EXPIRED,CANCELLED}protected TrainingAssignment(){}public void complete(){status=Status.COMPLETED;}public void fail(){status=Status.FAILED;}public void markOverdue(LocalDate today){if(dueDate!=null&&dueDate.isBefore(today)&&status!=Status.COMPLETED)status=Status.OVERDUE;}public Status getStatus(){return status;} public void transition(Status next,TrainingStatusEngine engine){engine.validate(status,next);status=next;} public Employee getEmployee(){return employee;} public TrainingCourse getCourse(){return course;}}
